// FitnessServer is the server API for Fitness service.
// All implementations must embed UnimplementedFitnessServer
// for forward compatibility.
//
// Walking competitions scoped by district and state, with server-side
// anti-cheat, a points ledger, and gift redemption. Identity, auth and tokens
// live in identity.v1; every "my" RPC here takes its subject from the token.
type FitnessServer interface {
	GetMyProfile(context.Context, *request.GetMyProfileRequest) (*response.GetMyProfileResponse, error)
	UpsertMyProfile(context.Context, *request.UpsertMyProfileRequest) (*response.UpsertMyProfileResponse, error)
	// States, or a state's districts, for the onboarding pickers.
	ListRegions(context.Context, *request.ListRegionsRequest) (*response.ListRegionsResponse, error)
	ListCompetitions(context.Context, *request.ListCompetitionsRequest) (*response.ListCompetitionsResponse, error)
	GetCompetition(context.Context, *request.GetCompetitionRequest) (*response.GetCompetitionResponse, error)
	JoinCompetition(context.Context, *request.JoinCompetitionRequest) (*response.JoinCompetitionResponse, error)
	LeaveCompetition(context.Context, *request.LeaveCompetitionRequest) (*response.LeaveCompetitionResponse, error)
	// Admin only: requires a USER_TYPE_ADMIN token. Walkers get FITNESS_ADMIN_REQUIRED.
	CreateCompetition(context.Context, *request.CreateCompetitionRequest) (*response.CreateCompetitionResponse, error)
	ListChallengeTemplates(context.Context, *request.ListChallengeTemplatesRequest) (*response.ListChallengeTemplatesResponse, error)
	// Remaining attempts, step cap and cooldown for today, so the app can
	// disable the start button instead of provoking a rejection.
	GetDailyQuota(context.Context, *request.GetDailyQuotaRequest) (*response.GetDailyQuotaResponse, error)
	// Consumes one of the day's attempts. Fails with CHALLENGE_DAILY_LIMIT_REACHED
	// once the cap is hit, and is idempotent on idempotency_key.
	StartChallenge(context.Context, *request.StartChallengeRequest) (*response.StartChallengeResponse, error)
	ListMyChallenges(context.Context, *request.ListMyChallengesRequest) (*response.ListMyChallengesResponse, error)
	AbandonChallenge(context.Context, *request.AbandonChallengeRequest) (*response.AbandonChallengeResponse, error)
	StartWalkSession(context.Context, *request.StartWalkSessionRequest) (*response.StartWalkSessionResponse, error)
	// Called every 30-60s while walking. The server recomputes distance and steps
	// from the samples; client totals are never trusted.
	SubmitWalkSamples(context.Context, *request.SubmitWalkSamplesRequest) (*response.SubmitWalkSamplesResponse, error)
	// Finalizes the session, runs the full anti-cheat pass and credits points.
	EndWalkSession(context.Context, *request.EndWalkSessionRequest) (*response.EndWalkSessionResponse, error)
	GetWalkSession(context.Context, *request.GetWalkSessionRequest) (*response.GetWalkSessionResponse, error)
	ListMyWalkSessions(context.Context, *request.ListMyWalkSessionsRequest) (*response.ListMyWalkSessionsResponse, error)
	GetMyStats(context.Context, *request.GetMyStatsRequest) (*response.GetMyStatsResponse, error)
	// Serves competition, weekly, monthly and all-time boards at any scope.
	GetLeaderboard(context.Context, *request.GetLeaderboardRequest) (*response.GetLeaderboardResponse, error)
	// District-vs-district or state-vs-state standings.
	GetRegionStandings(context.Context, *request.GetRegionStandingsRequest) (*response.GetRegionStandingsResponse, error)
	GetMyPointsBalance(context.Context, *request.GetMyPointsBalanceRequest) (*response.GetMyPointsBalanceResponse, error)
	ListMyPointsLedger(context.Context, *request.ListMyPointsLedgerRequest) (*response.ListMyPointsLedgerResponse, error)
	ListGifts(context.Context, *request.ListGiftsRequest) (*response.ListGiftsResponse, error)
	GetGift(context.Context, *request.GetGiftRequest) (*response.GetGiftResponse, error)
	// Reserves the points immediately; fulfilment moves it to FULFILLED or
	// refunds on rejection.
	RedeemGift(context.Context, *request.RedeemGiftRequest) (*response.RedeemGiftResponse, error)
	ListMyRedemptions(context.Context, *request.ListMyRedemptionsRequest) (*response.ListMyRedemptionsResponse, error)
	CancelRedemption(context.Context, *request.CancelRedemptionRequest) (*response.CancelRedemptionResponse, error)
	UpdateCompetition(context.Context, *request.UpdateCompetitionRequest) (*response.UpdateCompetitionResponse, error)
	// Ends a competition early and freezes its leaderboard.
	CancelCompetition(context.Context, *request.CancelCompetitionRequest) (*response.CancelCompetitionResponse, error)
	CreateChallengeTemplate(context.Context, *request.CreateChallengeTemplateRequest) (*response.CreateChallengeTemplateResponse, error)
	CreateGift(context.Context, *request.CreateGiftRequest) (*response.CreateGiftResponse, error)
	UpdateGift(context.Context, *request.UpdateGiftRequest) (*response.UpdateGiftResponse, error)
	// Moves a redemption to APPROVED, FULFILLED or REJECTED. Rejecting refunds
	// the reserved points via a compensating ledger entry.
	FulfilRedemption(context.Context, *request.FulfilRedemptionRequest) (*response.FulfilRedemptionResponse, error)
	ListAllRedemptions(context.Context, *request.ListAllRedemptionsRequest) (*response.ListAllRedemptionsResponse, error)
	ListFlaggedSessions(context.Context, *request.ListFlaggedSessionsRequest) (*response.ListFlaggedSessionsResponse, error)
	ReviewSession(context.Context, *request.ReviewSessionRequest) (*response.ReviewSessionResponse, error)
	mustEmbedUnimplementedFitnessServer()
}

